"""Discover CSV tables and infer types from complete, freshly read columns."""

from __future__ import annotations

import csv
from dataclasses import dataclass
from os import PathLike, fspath
from pathlib import Path
import re

from .errors import DataIOError, SemanticError


_INTEGER = re.compile(r"[+-]?[0-9]+")
_REAL = re.compile(r"[+-]?([0-9]+\.[0-9]*|\.[0-9]+|[0-9]+)([eE][+-]?[0-9]+)?")


@dataclass(frozen=True)
class Table:
    name: str
    columns: list[str]
    types: list[str]
    rows: list[tuple]


class Catalog:
    def __init__(self, data_dir: str | PathLike[str]) -> None:
        directory = fspath(data_dir)
        self._path = Path(directory)
        if not self._path.is_dir():
            raise DataIOError(f"data directory not found: {directory}")

    def _files(self) -> list[Path]:
        try:
            return [path for path in self._path.iterdir()
                    if path.name.lower().endswith(".csv") and path.is_file()]
        except OSError as error:
            raise DataIOError(f"{self._path.name}: {error.strerror}") from error

    def tables(self) -> list[str]:
        return sorted((path.name[:-4] for path in self._files()),
                      key=lambda name: (name.lower(), name))

    def load(self, name: str, line: int = 1, column: int = 1) -> Table:
        matches = [path for path in self._files()
                   if path.name[:-4].lower() == name.lower()]
        if not matches:
            raise SemanticError(f"unknown table '{name}'", line, column)
        if len(matches) > 1:
            raise DataIOError(f"ambiguous table file '{name}'")
        path = matches[0]
        columns = None
        raw_rows = []
        try:
            with path.open(encoding="utf-8-sig", newline="") as stream:
                reader = csv.reader(stream, strict=True)
                try:
                    for fields in reader:
                        if not fields:
                            continue
                        if columns is None:
                            columns = fields
                            seen = set()
                            for header in columns:
                                if not header:
                                    raise DataIOError(f"{path.name}: empty column name")
                                if header.lower() in seen:
                                    raise DataIOError(
                                        f"{path.name}: duplicate column '{header}'")
                                seen.add(header.lower())
                        elif len(fields) != len(columns):
                            raise DataIOError(
                                f"{path.name}: line {reader.line_num}: expected "
                                f"{len(columns)} fields, got {len(fields)}")
                        else:
                            raw_rows.append(fields)
                except csv.Error as error:
                    raise DataIOError(
                        f"{path.name}: line {reader.line_num}: malformed CSV") from error
        except UnicodeDecodeError as error:
            raise DataIOError(f"{path.name}: invalid UTF-8") from error
        except OSError as error:
            raise DataIOError(f"{path.name}: {error.strerror}") from error
        if columns is None:
            raise DataIOError(f"{path.name}: empty file")

        types = []
        for index in range(len(columns)):
            fields = [row[index] for row in raw_rows if row[index] != ""]
            if fields and all(_INTEGER.fullmatch(field) for field in fields):
                types.append("INTEGER")
            elif fields and all(_REAL.fullmatch(field) for field in fields):
                types.append("REAL")
            else:
                types.append("TEXT")
        converters = {"INTEGER": int, "REAL": float, "TEXT": str}
        rows = [tuple(None if field == "" else converters[kind](field)
                      for field, kind in zip(row, types)) for row in raw_rows]
        return Table(path.name[:-4], columns, types, rows)

    def schema(self, name: str) -> list[tuple[str, str]]:
        table = self.load(name)
        return list(zip(table.columns, table.types))

